459	  /**
460	   * Initialize or update text dimensions.
461	   * Updates this.width and this.height with the proper values.
462	   * Does not return dimensions.
463	   */
464	  initDimensions() {
465	    this._splitText();
466	    this._clearCache();
467	    this.dirty = true;
468	    if (this.path) {
469	      this.width = this.path.width;
470	      this.height = this.path.height;
471	    } else {
472	      this.width =
473	        this.calcTextWidth() || this.cursorWidth || this.MIN_TEXT_WIDTH;
474	      this.height = this.calcTextHeight();
475	    }
476	    if (this.textAlign.includes(JUSTIFY)) {
477	      // once text is measured we need to make space fatter to make justified text.
478	      this.enlargeSpaces();
479	    }
480	  }
