482	  /**
483	   * Enlarge space boxes and shift the others
484	   */
485	  enlargeSpaces() {
486	    let diffSpace,
487	      currentLineWidth,
488	      numberOfSpaces,
489	      accumulatedSpace,
490	      line,
491	      charBound,
492	      spaces;
493	    for (let i = 0, len = this._textLines.length; i < len; i++) {
494	      if (
495	        this.textAlign !== JUSTIFY &&
496	        (i === len - 1 || this.isEndOfWrapping(i))
497	      ) {
498	        continue;
499	      }
500	      accumulatedSpace = 0;
501	      line = this._textLines[i];
502	      currentLineWidth = this.getLineWidth(i);
503	      if (
504	        currentLineWidth < this.width &&
505	        (spaces = this.textLines[i].match(this._reSpacesAndTabs))
506	      ) {
507	        numberOfSpaces = spaces.length;
508	        diffSpace = (this.width - currentLineWidth) / numberOfSpaces;
509	        for (let j = 0; j <= line.length; j++) {
510	          charBound = this.__charBounds[i][j];
511	          if (this._reSpaceAndTab.test(line[j])) {
512	            charBound.width += diffSpace;
513	            charBound.kernedWidth += diffSpace;
514	            charBound.left += accumulatedSpace;
515	            accumulatedSpace += diffSpace;
516	          } else {
517	            charBound.left += accumulatedSpace;
518	          }
519	        }
520	      }
521	    }
522	  }
