524	  /**
525	   * Detect if the text line is ended with an hard break
526	   * text and itext do not have wrapping, return false
527	   * @return {Boolean}
528	   */
529	  isEndOfWrapping(lineIndex: number): boolean {
530	    return lineIndex === this._textLines.length - 1;
531	  }
