533	  /**
534	   * Detect if a line has a linebreak and so we need to account for it when moving
535	   * and counting style.
536	   * It return always 1 for text and Itext. Textbox has its own implementation
537	   * @return Number
538	   */
539	  missingNewlineOffset(lineIndex: number, skipWrapping?: boolean): 0 | 1;
540	  missingNewlineOffset(_lineIndex: number): 1 {
541	    return 1;
542	  }
