544	  /**
545	   * Returns 2d representation (lineIndex and charIndex) of cursor
546	   * @param {Number} selectionStart
547	   * @param {Boolean} [skipWrapping] consider the location for unwrapped lines. useful to manage styles.
548	   */
549	  get2DCursorLocation(selectionStart: number, skipWrapping?: boolean) {
550	    const lines = skipWrapping ? this._unwrappedTextLines : this._textLines;
551	    let i: number;
552	    for (i = 0; i < lines.length; i++) {
553	      if (selectionStart <= lines[i].length) {
554	        return {
555	          lineIndex: i,
556	          charIndex: selectionStart,
557	        };
558	      }
559	      selectionStart -=
560	        lines[i].length + this.missingNewlineOffset(i, skipWrapping);
561	    }
562	    return {
563	      lineIndex: i - 1,
564	      charIndex:
565	        lines[i - 1].length < selectionStart
566	          ? lines[i - 1].length
567	          : selectionStart,
568	    };
569	  }
