605	    const path = this.path;
606	    path && !path.isNotVisible() && path._render(ctx);
607	    this._setTextStyles(ctx);
608	    this._renderTextLinesBackground(ctx);
609	    this._renderTextDecoration(ctx, 'underline');
610	    this._renderText(ctx);
611	    this._renderTextDecoration(ctx, 'overline');
612	    this._renderTextDecoration(ctx, 'linethrough');
