699	  /**
700	   * Renders the text background for lines, taking care of style
701	   * @private
702	   * @param {CanvasRenderingContext2D} ctx Context to render on
703	   */
704	  _renderTextLinesBackground(ctx: CanvasRenderingContext2D) {
705	    if (!this.textBackgroundColor && !this.styleHas('textBackgroundColor')) {
706	      return;
707	    }
708	    const originalFill = ctx.fillStyle,
709	      leftOffset = this._getLeftOffset();
710	    let lineTopOffset = this._getTopOffset();
711	
712	    for (let i = 0, len = this._textLines.length; i < len; i++) {
713	      const heightOfLine = this.getHeightOfLine(i);
714	      if (
715	        !this.textBackgroundColor &&
716	        !this.styleHas('textBackgroundColor', i)
717	      ) {
718	        lineTopOffset += heightOfLine;
719	        continue;
720	      }
