864	  /**
865	   * measure a text line measuring all characters.
866	   * @param {Number} lineIndex line number
867	   */
868	  measureLine(lineIndex: number) {
869	    const lineInfo = this._measureLine(lineIndex);
870	    if (this.charSpacing !== 0) {
871	      lineInfo.width -= this._getWidthOfCharSpacing();
872	    }
873	    if (lineInfo.width < 0) {
874	      lineInfo.width = 0;
875	    }
