950	  /**
951	   * Calculate the angle  and the left,top position of the char that follow a path.
952	   * It appends it to graphemeInfo to be reused later at rendering
953	   * @private
954	   * @param {Number} positionInPath to be measured
955	   * @param {GraphemeBBox} graphemeInfo current grapheme box information
956	   * @param {Object} startingPoint position of the point
957	   */
958	  _setGraphemeOnPath(positionInPath: number, graphemeInfo: GraphemeBBox) {
959	    const centerPosition = positionInPath + graphemeInfo.kernedWidth / 2,
960	      path = this.path!;
961	
962	    // we are at currentPositionOnPath. we want to know what point on the path is.
963	    const info = getPointOnPath(path.path, centerPosition, path.segmentsInfo)!;
964	    graphemeInfo.renderLeft = info.x - path.pathOffset.x;
965	    graphemeInfo.renderTop = info.y - path.pathOffset.y;
966	    graphemeInfo.angle = info.angle + (this.pathSide === RIGHT ? Math.PI : 0);
967	  }
