1014	  /**
1015	   * Calculate height of line at 'lineIndex'
1016	   * @param {Number} lineIndex index of line to calculate
1017	   * @return {Number}
1018	   */
1019	  getHeightOfLine(lineIndex: number): number {
1020	    if (this.__lineHeights[lineIndex]) {
1021	      return this.__lineHeights[lineIndex];
1022	    }
1023	
1024	    // char 0 is measured before the line cycle because it needs to char
1025	    // emptylines
1026	    let maxHeight = this.getHeightOfChar(lineIndex, 0);
1027	    for (let i = 1, len = this._textLines[lineIndex].length; i < len; i++) {
1028	      maxHeight = Math.max(this.getHeightOfChar(lineIndex, i), maxHeight);
1029	    }
1030	
1031	    return (this.__lineHeights[lineIndex] =
1032	      maxHeight * this.lineHeight * this._fontSizeMult);
1033	  }
