1035	  /**
1036	   * Calculate text box height
1037	   */
1038	  calcTextHeight() {
1039	    let lineHeight,
1040	      height = 0;
1041	    for (let i = 0, len = this._textLines.length; i < len; i++) {
1042	      lineHeight = this.getHeightOfLine(i);
1043	      height += i === len - 1 ? lineHeight / this.lineHeight : lineHeight;
1044	    }
1045	    return height;
1046	  }
