1273	  handleFiller<T extends 'fill' | 'stroke'>(
1274	    ctx: CanvasRenderingContext2D,
1275	    property: `${T}Style`,
1276	    filler: TFiller | string,
1277	  ): { offsetX: number; offsetY: number } {
1278	    let offsetX: number, offsetY: number;
1279	    if (isFiller(filler)) {
1280	      if (
1281	        (filler as Gradient<'linear'>).gradientUnits === 'percentage' ||
1282	        (filler as Gradient<'linear'>).gradientTransform ||
1283	        (filler as Pattern).patternTransform
1284	      ) {
1285	        // need to transform gradient in a pattern.
1286	        // this is a slow process. If you are hitting this codepath, and the object
1287	        // is not using caching, you should consider switching it on.
1288	        // we need a canvas as big as the current object caching canvas.
1289	        offsetX = -this.width / 2;
1290	        offsetY = -this.height / 2;
1291	        ctx.translate(offsetX, offsetY);
1292	        ctx[property] = this._applyPatternGradientTransformText(filler);
1293	        return { offsetX, offsetY };
1294	      } else {
1295	        // is a simple gradient or pattern
1296	        ctx[property] = filler.toLive(ctx)!;
1297	        return this._applyPatternGradientTransform(ctx, filler);
1298	      }
1299	    } else {
1300	      // is a color
1301	      ctx[property] = filler;
1302	    }
1303	    return { offsetX: 0, offsetY: 0 };
1304	  }
