  let diffSpace, currentLineWidth, numberOfSpaces, accumulatedSpace, line, charBound, spaces;
  for (let i = 0, len = this._textLines.length; i < len; i++) {
    if (this.textAlign !== JUSTIFY && (i === len - 1 || this.isEndOfWrapping(i))) {
