  pathStartOffset: 0,
  pathSide: 'left',
  pathAlign: 'baseline',
  textDecorationThickness: 66.667,
};

function createTextObject() {
  return new FabricText('x');
}

describe('FabricText', () => {
  afterEach(() => {
    config.restoreDefaults();
  });

