1	import type { TClassProperties, TOptions } from '../typedefs';
2	import { IText } from './IText/IText';
3	import { classRegistry } from '../ClassRegistry';
4	import { createTextboxDefaultControls } from '../controls/commonControls';
5	import { JUSTIFY } from './Text/constants';
6	import type { TextStyleDeclaration } from './Text/StyledText';
7	import type { SerializedITextProps, ITextProps } from './IText/IText';
8	import type { ITextEvents } from './IText/ITextBehavior';
9	import type { TextLinesInfo } from './Text/Text';
10	import type { Control } from '../controls/Control';
11	
12	// @TODO: Many things here are configuration related and shouldn't be on the class nor prototype
13	// regexes, list of properties that are not suppose to change by instances, magic consts.
14	// this will be a separated effort
15	export const textboxDefaultValues: Partial<TClassProperties<Textbox>> = {
16	  minWidth: 20,
17	  dynamicMinWidth: 2,
18	  lockScalingFlip: true,
19	  noScaleCache: false,
20	  _wordJoiners: /[ \t\r]/,
21	  splitByGrapheme: false,
22	};
23	
24	export type GraphemeData = {
25	  wordsData: {
26	    word: string[];
27	    width: number;
28	  }[][];
29	  largestWordWidth: number;
30	};
31	
32	export type StyleMap = Record<string, { line: number; offset: number }>;
33	
34	// @TODO this is not complete
35	interface UniqueTextboxProps {
36	  minWidth: number;
37	  splitByGrapheme: boolean;
38	  dynamicMinWidth: number;
39	  _wordJoiners: RegExp;
40	}
41	
42	export interface SerializedTextboxProps
43	  extends SerializedITextProps,
44	    Pick<UniqueTextboxProps, 'minWidth' | 'splitByGrapheme'> {}
45	
46	export interface TextboxProps extends ITextProps, UniqueTextboxProps {}
47	
48	/**
49	 * Textbox class, based on IText, allows the user to resize the text rectangle
50	 * and wraps lines automatically. Textboxes have their Y scaling locked, the
51	 * user can only change width. Height is adjusted automatically based on the
52	 * wrapping of lines.
53	 */
54	export class Textbox<
55	    Props extends TOptions<TextboxProps> = Partial<TextboxProps>,
56	    SProps extends SerializedTextboxProps = SerializedTextboxProps,
57	    EventSpec extends ITextEvents = ITextEvents,
58	  >
59	  extends IText<Props, SProps, EventSpec>
60	  implements UniqueTextboxProps
61	{
62	  /**
63	   * Minimum width of textbox, in pixels.
64	   * @type Number
65	   */
66	  declare minWidth: number;
67	
68	  /**
69	   * Minimum calculated width of a textbox, in pixels.
70	   * fixed to 2 so that an empty textbox cannot go to 0
71	   * and is still selectable without text.
72	   * @type Number
73	   */
74	  declare dynamicMinWidth: number;
75	
76	  /**
77	   * Use this boolean property in order to split strings that have no white space concept.
78	   * this is a cheap way to help with chinese/japanese
79	   * @type Boolean
80	   * @since 2.6.0
81	   */
82	  declare splitByGrapheme: boolean;
83	
84	  declare _wordJoiners: RegExp;
85	
86	  declare _styleMap: StyleMap;
87	
88	  declare isWrapping: boolean;
89	
90	  static type = 'Textbox';
91	
92	  static textLayoutProperties = [...IText.textLayoutProperties, 'width'];
93	
94	  static ownDefaults = textboxDefaultValues;
95	
96	  static getDefaults(): Record<string, any> {
97	    return {
98	      ...super.getDefaults(),
99	      ...Textbox.ownDefaults,
100	    };
101	  }
102	
103	  /**
104	   * Constructor
105	   * @param {String} text Text string
106	   * @param {Object} [options] Options object
107	   */
108	  constructor(text: string, options?: Props) {
109	    super(text, { ...Textbox.ownDefaults, ...options } as Props);
110	  }
111	
112	  /**
113	   * Creates the default control object.
114	   * If you prefer to have on instance of controls shared among all objects
115	   * make this function return an empty object and add controls to the ownDefaults object
116	   */
117	  static createControls(): { controls: Record<string, Control> } {
118	    return { controls: createTextboxDefaultControls() };
119	  }
120	
121	  /**
122	   * Unlike superclass's version of this function, Textbox does not update
123	   * its width.
124	   * @private
125	   * @override
126	   */
127	  initDimensions() {
128	    if (!this.initialized) {
129	      return;
130	    }
131	    this.isEditing && this.initDelayedCursor();
132	    this._clearCache();
133	    // clear dynamicMinWidth as it will be different after we re-wrap line
134	    this.dynamicMinWidth = 0;
135	    // wrap lines
136	    this._styleMap = this._generateStyleMap(this._splitText());
137	    // if after wrapping, the width is smaller than dynamicMinWidth, change the width and re-wrap
138	    if (this.dynamicMinWidth > this.width) {
139	      this._set('width', this.dynamicMinWidth);
140	    }
141	    if (this.textAlign.includes(JUSTIFY)) {
142	      // once text is measured we need to make space fatter to make justified text.
143	      this.enlargeSpaces();
144	    }
145	    // clear cache and re-calculate height
146	    this.height = this.calcTextHeight();
147	  }
148	
149	  /**
150	   * Generate an object that translates the style object so that it is
151	   * broken up by visual lines (new lines and automatic wrapping).
152	   * The original text styles object is broken up by actual lines (new lines only),
153	   * which is only sufficient for Text / IText
154	   * @private
155	   */
156	  _generateStyleMap(textInfo: TextLinesInfo): StyleMap {
157	    let realLineCount = 0,
158	      realLineCharCount = 0,
159	      charCount = 0;
160	    const map: StyleMap = {};
161	
162	    for (let i = 0; i < textInfo.graphemeLines.length; i++) {
163	      if (textInfo.graphemeText[charCount] === '\n' && i > 0) {
164	        realLineCharCount = 0;
165	        charCount++;
166	        realLineCount++;
167	      } else if (
168	        !this.splitByGrapheme &&
169	        this._reSpaceAndTab.test(textInfo.graphemeText[charCount]) &&
170	        i > 0
171	      ) {
172	        // this case deals with space's that are removed from end of lines when wrapping
173	        realLineCharCount++;
174	        charCount++;
175	      }
176	
177	      map[i] = { line: realLineCount, offset: realLineCharCount };
178	
179	      charCount += textInfo.graphemeLines[i].length;
180	      realLineCharCount += textInfo.graphemeLines[i].length;
181	    }
182	
183	    return map;
184	  }
185	
186	  /**
187	   * Returns true if object has a style property or has it on a specified line
188	   * @param {Number} lineIndex
189	   * @return {Boolean}
190	   */
191	  styleHas(property: keyof TextStyleDeclaration, lineIndex: number): boolean {
192	    if (this._styleMap && !this.isWrapping) {
193	      const map = this._styleMap[lineIndex];
194	      if (map) {
195	        lineIndex = map.line;
196	      }
197	    }
198	    return super.styleHas(property, lineIndex);
199	  }
200	
201	  /**
202	   * Returns true if object has no styling or no styling in a line
203	   * @param {Number} lineIndex , lineIndex is on wrapped lines.
204	   * @return {Boolean}
205	   */
206	  isEmptyStyles(lineIndex: number): boolean {
207	    if (!this.styles) {
208	      return true;
209	    }
210	    let offset = 0,
211	      nextLineIndex = lineIndex + 1,
212	      nextOffset: number,
213	      shouldLimit = false;
214	    const map = this._styleMap[lineIndex],
215	      mapNextLine = this._styleMap[lineIndex + 1];
216	    if (map) {
217	      lineIndex = map.line;
218	      offset = map.offset;
219	    }
220	    if (mapNextLine) {
221	      nextLineIndex = mapNextLine.line;
222	      shouldLimit = nextLineIndex === lineIndex;
223	      nextOffset = mapNextLine.offset;
224	    }
225	    const obj =
226	      typeof lineIndex === 'undefined'
227	        ? this.styles
228	        : { line: this.styles[lineIndex] };
229	    for (const p1 in obj) {
230	      for (const p2 in obj[p1]) {
231	        const p2Number = parseInt(p2, 10);
232	        if (p2Number >= offset && (!shouldLimit || p2Number < nextOffset!)) {
233	          for (const p3 in obj[p1][p2]) {
234	            return false;
235	          }
236	        }
237	      }
238	    }
239	    return true;
240	  }
241	
242	  /**
243	   * @protected
244	   * @param {Number} lineIndex
245	   * @param {Number} charIndex
246	   * @return {TextStyleDeclaration} a style object reference to the existing one or a new empty object when undefined
247	   */
248	  _getStyleDeclaration(
249	    lineIndex: number,
250	    charIndex: number,
251	  ): TextStyleDeclaration {
252	    if (this._styleMap && !this.isWrapping) {
253	      const map = this._styleMap[lineIndex];
254	      if (!map) {
255	        return {};
256	      }
257	      lineIndex = map.line;
258	      charIndex = map.offset + charIndex;
259	    }
260	    return super._getStyleDeclaration(lineIndex, charIndex);
261	  }
262	
263	  /**
264	   * @param {Number} lineIndex
265	   * @param {Number} charIndex
266	   * @param {Object} style
267	   * @private
268	   */
269	  protected _setStyleDeclaration(
270	    lineIndex: number,
271	    charIndex: number,
272	    style: object,
273	  ) {
274	    const map = this._styleMap[lineIndex];
275	    super._setStyleDeclaration(map.line, map.offset + charIndex, style);
276	  }
277	
278	  /**
279	   * @param {Number} lineIndex
280	   * @param {Number} charIndex
281	   * @private
282	   */
283	  protected _deleteStyleDeclaration(lineIndex: number, charIndex: number) {
284	    const map = this._styleMap[lineIndex];
285	    super._deleteStyleDeclaration(map.line, map.offset + charIndex);
286	  }
287	
288	  /**
289	   * probably broken need a fix
290	   * Returns the real style line that correspond to the wrapped lineIndex line
291	   * Used just to verify if the line does exist or not.
292	   * @param {Number} lineIndex
293	   * @returns {Boolean} if the line exists or not
294	   * @private
295	   */
296	  protected _getLineStyle(lineIndex: number): boolean {
297	    const map = this._styleMap[lineIndex];
298	    return !!this.styles[map.line];
299	  }
300	
301	  /**
302	   * Set the line style to an empty object so that is initialized
303	   * @param {Number} lineIndex
304	   * @param {Object} style
305	   * @private
306	   */
307	  protected _setLineStyle(lineIndex: number) {
308	    const map = this._styleMap[lineIndex];
309	    super._setLineStyle(map.line);
310	  }
311	
312	  /**
313	   * Wraps text using the 'width' property of Textbox. First this function
314	   * splits text on newlines, so we preserve newlines entered by the user.
315	   * Then it wraps each line using the width of the Textbox by calling
316	   * _wrapLine().
317	   * @param {Array} lines The string array of text that is split into lines
318	   * @param {Number} desiredWidth width you want to wrap to
319	   * @returns {Array} Array of lines
320	   */
321	  _wrapText(lines: string[], desiredWidth: number): string[][] {
322	    this.isWrapping = true;
323	    // extract all thewords and the widths to optimally wrap lines.
324	    const data = this.getGraphemeDataForRender(lines);
325	    const wrapped: string[][] = [];
