import { describe, expect, it } from 'vitest';
import { FabricText } from './Text/Text';

describe('bug repro', () => {
  it('two multiline texts both have real width', () => {
    const t1 = new FabricText('e\na', { lineHeight: 0.3 });
    const t2 = new FabricText('f\ng', { lineHeight: 0.3 });
    console.log('T1', t1.width, t1.height, JSON.stringify(t1.__lineWidths));
    console.log('T2', t2.width, t2.height, JSON.stringify(t2.__lineWidths));
    expect(t1.width).toBeGreaterThan(5);
    expect(t2.width).toBeGreaterThan(5);
  });
});

