  const shouldRedraw = dimensionsChanged || zoomChanged;

  if (shouldRedraw) {
    if (width !== canvas.width || height !== canvas.height) {
      canvas.width = width;
      canvas.height = height;
    } else {
      context.setTransform(1, 0, 0, 1, 0, 0);
