import { createCanvas, registerFont, loadImage } from 'canvas';
import path from 'node:path';
import fs from 'node:fs';

const dir = path.resolve('./test/fixtures');
for (const [f, w, s] of [
  ['Ubuntu-Regular.ttf', 'regular', 'normal'],
  ['Ubuntu-Bold.ttf', 'bold', 'normal'],
  ['Ubuntu-Italic.ttf', 'regular', 'italic'],
  ['Ubuntu-BoldItalic.ttf', 'bold', 'italic'],
]) {
  registerFont(path.join(dir, f), { family: 'Ubuntu', weight: w, style: s });
}

const fabric = await import('./dist/index.node.mjs');
// load transpiled testcases
const tc = await import('./_text_cases.mjs');
const cases = tc.renderTests || tc.default;

const goldenDir = './e2e/tests/visual-output/rendering/index.spec.ts-snapshots/text';

function diffImages(imgData, golden, W, H) {
  let diff = 0;
  const a = imgData.data, b = golden.data;
  for (let i = 0; i < a.length; i += 4) {
    const da = Math.abs(a[i]-b[i]) + Math.abs(a[i+1]-b[i+1]) + Math.abs(a[i+2]-b[i+2]) + Math.abs(a[i+3]-b[i+3]);
    if (da > 40) diff++;
  }
  return diff;
}

for (const t of cases) {
  if (t.disabled === 'node' || t.disabled === true) { console.log('SKIP(node)', t.golden); continue; }
  const [W, H] = t.size;
  const canvas = new fabric.StaticCanvas(null, { width: W, height: H, renderOnAddRemove: false });
  canvas.backgroundColor = 'white';
  fabric.FabricObject.ownDefaults.objectCaching = false;
  try {
    await t.renderFunction(canvas, fabric);
    canvas.renderAll();
  } catch (e) {
    console.log('ERR ', t.golden, e.message);
    continue;
  }
  const el = canvas.getElement();
  const ctx = el.getContext('2d');
  const imgData = ctx.getImageData(0, 0, W, H);
  const gpath = path.join(goldenDir, t.golden);
  if (!fs.existsSync(gpath)) { console.log('NOGOLD', t.golden); continue; }
  const gimg = await loadImage(gpath);
  const gc = createCanvas(gimg.width, gimg.height);
  const gctx = gc.getContext('2d');
  gctx.drawImage(gimg, 0, 0);
  if (gimg.width !== W || gimg.height !== H) {
    console.log('SIZEDIFF', t.golden, `render ${W}x${H} golden ${gimg.width}x${gimg.height}`);
    continue;
  }
  const gdata = gctx.getImageData(0, 0, W, H);
  const d = diffImages(imgData, gdata, W, H);
  const ratio = d / (W*H);
  const flag = ratio > (t.percentage || 0.02) ? '  <<< FAIL' : '';
  console.log(`${t.golden.padEnd(30)} diffpx=${String(d).padStart(6)} ratio=${ratio.toFixed(4)} thresh=${t.percentage}${flag}`);
}

